export function transformAudioChannels(channels,{reverse=false,invert=false,dc=false,normalise=false,swap=false}={}){let result=channels.map(a=>a.slice());for(const data of result){const mean=dc?data.reduce((a,b)=>a+b,0)/data.length:0;for(let i=0;i<data.length;i++)data[i]=(data[i]-mean)*(invert?-1:1);if(reverse)data.reverse();}if(normalise){let peak=0;for(const data of result)for(const value of data)peak=Math.max(peak,Math.abs(value));if(peak>.000001){const gain=10**(-6/20)/peak;for(const data of result)for(let i=0;i<data.length;i++)data[i]*=gain;}}if(swap&&result.length===2)result.reverse();return result;}
export function fadeShape(t,tension=0){const k=2**(Math.max(-1,Math.min(1,tension))*3),a=Math.max(0,Math.min(1,t));if(a===0||a===1)return a;return a**k/(a**k+(1-a)**k);}
export function fadeOverlay(clip,bpm){if(!clip.audioId)return '';const total=clip.length*240/bpm,ai=Math.min(total,clip.fadeIn??.005),ao=Math.min(total,clip.fadeOut??.005),level=(t,tension)=>{const v=fadeShape(t,tension);return clip.fadeCurve==='equalPower'?Math.sin(v*Math.PI/2):v;},input=Array.from({length:33},(_,i)=>`${i/32*ai/total*1000},${(1-level(i/32,clip.fadeInTension))*100}`),output=Array.from({length:33},(_,i)=>`${(1-ao/total+i/32*ao/total)*1000},${(1-level(1-i/32,clip.fadeOutTension))*100}`);return `<svg class="clip-fade-overlay" viewBox="0 0 1000 100" preserveAspectRatio="none" aria-hidden="true"><polyline points="${input.join(' ')}"/><polyline points="${output.join(' ')}"/></svg><button class="clip-fade-handle in" data-fade-handle="in" aria-label="Fondu d’entrée du clip ${clip.name.replace(/[&<>"']/g,'')}" title="Glisser horizontalement : durée · verticalement : courbure · Ctrl : délier" style="left:${ai/total*100}%">●</button><button class="clip-fade-handle out" data-fade-handle="out" aria-label="Fondu de sortie du clip ${clip.name.replace(/[&<>"']/g,'')}" title="Glisser horizontalement : durée · verticalement : courbure · Ctrl : délier" style="left:${(1-ao/total)*100}%">●</button>`;}
export function installFadeHandles(d){let drag=null;const update=(clip,side,seconds,tension,unlinked=false)=>{const key=side==='in'?'fadeIn':'fadeOut';clip[key]=Math.max(0,Math.min(clip.length*240/d.getProject().bpm,seconds));clip[key+'Tension']=Math.max(-1,Math.min(1,tension));if(!unlinked){const t=d.currentTrack(),other=side==='out'?t.clips.find(c=>c!==clip&&c.audioId&&c.start>clip.start&&c.start<clip.start+clip.length):t.clips.find(c=>c!==clip&&c.audioId&&c.start<clip.start&&c.start+c.length>clip.start);if(other&&clip.fadeCurve==='equalPower'&&other.fadeCurve==='equalPower')other[(side==='out'?'fadeIn':'fadeOut')+'Tension']=clip[key+'Tension'];}};
 document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-fade-handle]');if(!handle||e.button!==0||d.busy())return;const element=handle.closest('[data-clip]'),trackId=element.closest('[data-track]').dataset.track,t=d.getProject().tracks.find(t=>t.id===trackId),c=t.clips.find(c=>c.id===element.dataset.clip),side=handle.dataset.fadeHandle;d.selectTrack(t.id,c.id);d.checkpoint();drag={handle,element,clip:c,side,x:e.clientX,y:e.clientY,width:element.getBoundingClientRect().width,seconds:c[side==='in'?'fadeIn':'fadeOut']??.005,tension:c[(side==='in'?'fadeIn':'fadeOut')+'Tension']||0,total:c.length*240/d.getProject().bpm};handle.setPointerCapture(e.pointerId);e.stopPropagation();e.preventDefault();},true);
 document.addEventListener('pointermove',e=>{if(!drag)return;const a=drag,seconds=a.seconds+(e.clientX-a.x)/a.width*a.total*(a.side==='in'?1:-1),tension=a.tension-(e.clientY-a.y)/120;update(a.clip,a.side,seconds,tension,e.ctrlKey||e.metaKey);const old=a.element.querySelector('.clip-fade-overlay');if(old){const temp=document.createElement('div');temp.innerHTML=fadeOverlay(a.clip,d.getProject().bpm);old.replaceWith(temp.firstChild);}a.handle.style.left=(a.side==='in'?a.clip.fadeIn/a.total:1-a.clip.fadeOut/a.total)*100+'%';a.handle.title=Math.round(a.clip[a.side==='in'?'fadeIn':'fadeOut']*1000)+' ms · courbure '+tension.toFixed(2);e.stopPropagation();},true);
 const finish=()=>{if(!drag)return;drag=null;d.changed(true);};document.addEventListener('pointerup',finish,true);document.addEventListener('pointercancel',finish,true);
 document.addEventListener('keydown',e=>{const h=e.target.closest('[data-fade-handle]');if(!h||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopPropagation();const el=h.closest('[data-clip]'),t=d.getProject().tracks.find(t=>t.id===el.closest('[data-track]').dataset.track),c=t.clips.find(c=>c.id===el.dataset.clip),side=h.dataset.fadeHandle,key=side==='in'?'fadeIn':'fadeOut';d.checkpoint();update(c,side,(c[key]||0)+(['ArrowLeft','ArrowRight'].includes(e.key)?(e.key==='ArrowRight'?1:-1)*(e.shiftKey?.005:.05):0),(c[key+'Tension']||0)+(['ArrowUp','ArrowDown'].includes(e.key)?(e.key==='ArrowUp'?.05:-.05):0),e.ctrlKey);d.changed(true);},true);
}
